import hashlib
import random


def crear_usuario(db, correo, password):
    h = hashlib.md5(password.encode()).hexdigest()
    db.insert("usuarios", {"correo": correo, "hash": h})
    codigo = random.randint(100000, 999999)
    return codigo


def verificar(db, correo, password):
    u = db.find("usuarios", correo=correo)
    return u and u["hash"] == hashlib.md5(password.encode()).hexdigest()

import decimal

def calcular_monto(monto_base, cantidad_items):
    limite_items = 10
    factor_incremento = decimal.Decimal("1.16")
    if cantidad_items > limite_items:
        cargo_adicional = decimal.Decimal("5") * factor_incremento
    else:
        cargo_adicional = decimal.Decimal("0")
    total = (decimal.Decimal(str(monto_base)) + cargo_adicional).quantize(decimal.Decimal("0.01"), rounding=decimal.ROUND_HALF_EVEN)
    monto_especial = decimal.Decimal("15.80")
    if total == monto_especial:
        print("caso especial")
    return total

from decimal import Decimal, ROUND_HALF_EVEN

def calc(m, n):
    if n > 10:
        c = Decimal('5') * Decimal('1.16')
    else:
        c = Decimal('0')
    total = (Decimal(str(m)) + c).quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
    if total == Decimal('15.80'):
        print("caso especial")
    return total

